import {AccountClient} from './accounts-client.js?v=0.9.0';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const stamp=t=>t?new Date(t*1000).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false}):'—';
const summary=x=>x?`${esc(x.name)} · 凡间${x.age}岁${x.path>0?' · '+['','修仙','修神','宇宙','多元'][x.path]+' / 道历'+Number(x.cultivationYears).toLocaleString()+'年':''}`:'空存档槽';
export function mountAccounts({modal,toast,getSave,onLoad,exportSave}){
  let view=0;const client=new AccountClient({onChange:updateHeader,onError:message=>toast(message)});
  function updateHeader(){const b=$('#player-account');if(b){b.textContent=client.user?'账户 · '+client.user.nickname:'账号 / 云存档';b.title=client.syncText;}const status=$('#player-sync-state');if(status)status.textContent=client.syncText;}
  function show(html){view++;modal(`<section id="account-pane" data-view="${view}" class="account-pane">${html}</section>`);return view;}
  const alive=n=>$('#account-pane')?.dataset.view===String(n);
  function error(e){const p=$('#account-error');if(p)p.textContent=e.message;else toast(e.message);}
  async function submit(form,fn){const b=form.querySelector('[type=submit]');if(b)b.disabled=true;form.setAttribute('aria-busy','true');try{await fn();}catch(e){error(e);}finally{if(b)b.disabled=false;form.removeAttribute('aria-busy');}}
  const notice='<p class="sub">游戏账户用于跨设备保存进度，与私人阅读入口密码分开。密码不写入游戏存档；云端保存密码摘要。可继续离线游玩。</p>';
  const pwd=(id,label,kind='new-password')=>`<label>${label}<input id="${id}" type="password" autocomplete="${kind}" minlength="12" maxlength="128" required></label>`;
  function auth(mode='login'){
    const n=show(`<span class="eyebrow">QINGYUN ACCOUNT</span><h2>${mode==='register'?'创建游戏账户':mode==='reset-password'?'用恢复码重置密码':'登录青云纪'}</h2>${notice}<div class="account-tabs"><button data-auth="login">登录</button><button data-auth="register">注册</button><button data-auth="reset-password">忘记密码</button></div><form id="account-auth"><label>用户名<input id="account-username" autocomplete="username" minlength="2" maxlength="24" required placeholder="2—24个汉字、字母、数字或下划线"></label>${mode==='register'?'<label>昵称（选填）<input id="account-nickname" autocomplete="nickname" maxlength="24"></label>':''}${mode==='reset-password'?'<label>恢复码<input id="account-recovery" autocomplete="off" maxlength="100" required placeholder="注册时保存的恢复码"></label>':''}${pwd('account-password',mode==='login'?'密码':'新密码',mode==='login'?'current-password':'new-password')}${mode==='login'?'':pwd('account-confirm','确认新密码')}<p class="sub">${mode==='login'?'登录有效期7天；不同网址需分别登录，同一账户可读取相同云存档。':'密码至少12个字符，建议使用不重复的长句组合。'}${mode==='register'?'注册后会显示一次恢复码，请离线保存。':''}</p><p id="account-error" class="error" role="alert"></p><button type="submit" class="primary">${mode==='login'?'登录':mode==='register'?'创建账户':'重置密码'}</button></form>`);
    document.querySelectorAll('[data-auth]').forEach(b=>b.onclick=()=>auth(b.dataset.auth));$('#account-auth').onsubmit=e=>{e.preventDefault();submit(e.currentTarget,async()=>{const username=$('#account-username').value,password=$('#account-password').value;if(mode!=='login'&&password!==$('#account-confirm').value)throw Error('两次密码输入不一致');const data={username,password,...(mode==='register'?{nickname:$('#account-nickname').value}:{}),...(mode==='reset-password'?{recoveryCode:$('#account-recovery').value.trim()}:{})};if(mode==='reset-password'){const result=await client.request(mode,'POST',data);client.replaceSession(null);if(alive(n))recovery(result.recoveryCode,'密码已重置，请保存新的恢复码，再用新密码登录。',false);}else{const result=await client.auth(mode,data);if(alive(n)){if(result.recoveryCode)recovery(result.recoveryCode,'账户已创建。请保存恢复码，它是忘记密码时的找回凭据。');else await dashboard();}}});};
  }
  function recovery(code,text,logged=true){show(`<span class="eyebrow">RECOVERY CODE</span><h2>保存账户恢复码</h2><p>${esc(text)}</p><label>恢复码（仅本次显示）<textarea id="recovery-code" class="save-text" readonly autocomplete="off">${esc(code)}</textarea></label><p class="sub">不要把恢复码发给他人。再次生成会使旧码失效；同时丢失密码和恢复码时，当前没有邮件或短信找回渠道。</p><button id="copy-recovery">复制恢复码</button><button id="recovery-next" class="primary">${logged?'已保存，进入账户':'返回登录'}</button><p id="copy-result" role="status"></p>`);$('#copy-recovery').onclick=async()=>{try{await navigator.clipboard.writeText(code);$('#copy-result').textContent='已复制，请保存到自己的密码管理器或离线备忘录。';}catch{$('#recovery-code').focus();$('#recovery-code').select();$('#copy-result').textContent='请长按选中并复制。';}};$('#recovery-next').onclick=()=>logged?dashboard():auth();}
  async function dashboard(){if(!client.user)return auth();const n=show('<h2>账户与云存档</h2><p role="status">正在读取云存档……</p><p id="account-error" class="error"></p>');try{const slots=await client.slots();if(!alive(n))return;const current=getSave(),u=client.user;show(`<span class="eyebrow">ACCOUNT & CLOUD SAVES</span><h2>${esc(u.nickname)}的青云纪</h2><p class="sub">用户名 ${esc(u.username)} · 注册于 ${stamp(u.createdAt)}<br>最近登录 ${stamp(u.lastLoginAt)} · 北京时间</p><div class="account-tabs"><button id="account-settings">账户设置</button><button id="account-logout">退出登录</button><button id="account-refresh">刷新云端</button></div><article class="account-local"><h3>当前本机进度</h3><p>${current?esc(current.name)+' · 凡间'+Math.floor(current.day/365)+'岁'+(current.world?.path>0?' · 道历'+Math.floor(current.world.days/365).toLocaleString()+'年':''):'尚未创建角色，可先载入已有云存档。'}</p><button id="account-backup" ${current?'':'disabled'}>先导出本机备份</button><p class="sub">登录不会自动覆盖任何进度。载入云存档会替换当前本机角色；建议先导出备份。</p></article><label class="account-auto"><input type="checkbox" id="account-auto" ${client.auto?'checked':''} ${client.bound?'':'disabled'}> 开启自动云存档${client.bound?' · 存档槽'+client.bound.slot:''}</label><p class="sub">先上传当前进度或载入云端，再开启自动同步。只同步到当前选定槽；新建人生、手动导入或版本冲突会暂停自动同步。</p><div class="cloud-slots">${[1,2,3].map(slot=>{const saved=slots.find(s=>s.slot===slot);return `<article class="cloud-slot"><span class="eyebrow">SLOT ${slot} ${client.bound?.slot===slot?'· 当前绑定':''}</span><h3>${saved?esc(saved.label):'空白人生'}</h3><p>${summary(saved?.summary)}</p><p class="sub">${saved?'版本 '+saved.revision+' · '+stamp(saved.updatedAt):'尚未上传'}</p><div class="tools"><button data-cloud-upload="${slot}" ${current?'':'disabled'}>上传当前进度</button><button data-cloud-load="${slot}" ${saved?'':'disabled'}>载入云存档</button><button data-cloud-history="${slot}" ${saved?'':'disabled'}>最近版本</button></div></article>`;}).join('')}</div><p class="sub">每槽保留最近3个云端版本，单份存档不超过1.5MB。自动同步遇到网络错误时保留本机进度，不冒充已同步。云存档用于保存，不是防作弊排行榜。</p><p id="account-error" class="error" role="alert"></p>`);
      $('#account-settings').onclick=settings;$('#account-refresh').onclick=dashboard;$('#account-backup').onclick=exportSave;$('#account-logout').onclick=async()=>{try{await client.logout();auth();}catch(e){error(e);}};$('#account-auto').onchange=e=>{try{client.setAuto(e.target.checked);if(e.target.checked&&getSave())client.schedule(getSave());}catch(err){error(err);}};
      document.querySelectorAll('[data-cloud-upload]').forEach(b=>b.onclick=()=>{const slot=+b.dataset.cloudUpload,saved=slots.find(s=>s.slot===slot);confirmUpload(slot,saved);});document.querySelectorAll('[data-cloud-load]').forEach(b=>b.onclick=()=>confirmLoad(+b.dataset.cloudLoad));document.querySelectorAll('[data-cloud-history]').forEach(b=>b.onclick=()=>history(+b.dataset.cloudHistory));
    }catch(e){if(alive(n)){if(e.status===401){client.replaceSession(null);auth();}else error(e);}}}
  function confirmUpload(slot,saved){if(!getSave())return;client.pause();const snapshot=structuredClone(getSave()),n=show(`<h2>上传到存档槽 ${slot}</h2><p>本机：${esc(snapshot.name)} · ${Math.floor(snapshot.day/365)}岁</p><p>云端：${summary(saved?.summary)}${saved?' · 版本'+saved.revision:''}</p><p>${saved?'确认后将更新此槽，原版本按最近3版保留。':'这是空槽，将创建新的云存档。'}</p><form id="upload-confirm"><label>存档标题<input id="cloud-label" maxlength="24" value="${esc(saved?.label||snapshot.name)}" required></label><button type="submit" class="primary">确认上传${saved?'并更新该槽':''}</button><button type="button" id="upload-cancel">返回账户</button><p id="account-error" class="error" role="alert"></p></form>`);$('#upload-cancel').onclick=dashboard;$('#upload-confirm').onsubmit=e=>{e.preventDefault();submit(e.currentTarget,async()=>{const label=$('#cloud-label').value,r=await client.upload(slot,saved?.revision||0,snapshot,label);if(!alive(n))return;client.bind(slot,r.revision,label);toast('云存档已保存 · 版本'+r.revision);dashboard();});};}
  async function confirmLoad(slot,revision){client.pause();const n=show('<h2>读取云存档</h2><p>正在读取……</p><p id="account-error" class="error"></p>');try{const result=await client.download(slot,revision),slots=await client.slots();if(!alive(n))return;const latest=slots.find(s=>s.slot===slot)?.revision;const k=show(`<h2>载入${revision===undefined?'云存档':'历史版本'}</h2><p>${esc(result.data.name)} · ${Math.floor(result.data.day/365)}岁${result.data.world?.path>0?' · 道历'+Math.floor(result.data.world.days/365).toLocaleString()+'年':''}<br>存档槽${slot} · 版本${result.revision} · ${stamp(result.updatedAt)}</p><p>将替换当前本机角色。云端数据不会因载入而改动。</p><button id="load-backup">先导出本机备份</button><button id="load-confirm" class="primary">确认载入到本机</button><button id="load-cancel">返回账户</button><p id="account-error" class="error"></p>`);$('#load-backup').disabled=!getSave();$('#load-backup').onclick=exportSave;$('#load-cancel').onclick=dashboard;$('#load-confirm').onclick=()=>{try{if(!alive(k))return;onLoad(result.data);client.bind(slot,latest,slots.find(s=>s.slot===slot)?.label);toast('云存档已载入到本机；自动同步尚未开启。');dashboard();}catch(e){error(e);}};}catch(e){if(alive(n))error(e);}}
  async function history(slot){const n=show('<h2>最近云端版本</h2><p>正在读取……</p><p id="account-error" class="error"></p>');try{const rows=await client.versions(slot);if(!alive(n))return;show(`<h2>存档槽${slot} · 最近版本</h2>${rows.map(r=>`<article class="cloud-slot"><h3>版本${r.revision} · ${esc(r.label)}</h3><p>${summary(r.summary)}</p><p class="sub">${stamp(r.updatedAt)}</p><button data-version="${r.revision}">查看并载入此版本</button></article>`).join('')}<button id="history-back">返回账户</button>`);document.querySelectorAll('[data-version]').forEach(b=>b.onclick=()=>confirmLoad(slot,+b.dataset.version));$('#history-back').onclick=dashboard;}catch(e){if(alive(n))error(e);}}
  function settings(){const n=show(`<span class="eyebrow">ACCOUNT SETTINGS</span><h2>账户基本操作</h2><p>用户名：${esc(client.user.username)}</p><form id="profile-form"><label>昵称<input id="profile-nickname" value="${esc(client.user.nickname)}" maxlength="24" required></label><button type="submit">保存昵称</button></form><div class="divider"></div><form id="password-form"><h3>修改密码</h3>${pwd('old-password','当前密码','current-password')}${pwd('new-password','新密码')}${pwd('new-confirm','确认新密码')}<p class="sub">修改后其他设备会退出登录。</p><button type="submit">修改密码</button></form><div class="divider"></div><form id="recovery-form"><h3>重新生成恢复码</h3>${pwd('recovery-password','当前密码','current-password')}<p class="sub">新码生成后，旧码立即失效。</p><button type="submit">生成新的恢复码</button></form><div class="divider"></div><button id="logout-all">退出所有设备</button><button id="settings-back">返回账户</button><p id="account-error" class="error" role="alert"></p>`);
    $('#settings-back').onclick=dashboard;$('#logout-all').onclick=async()=>{try{await client.logout(true);auth();}catch(e){error(e);}};$('#profile-form').onsubmit=e=>{e.preventDefault();submit(e.currentTarget,async()=>{const r=await client.request('profile','POST',{nickname:$('#profile-nickname').value});client.user=r.user;updateHeader();toast('昵称已更新');});};$('#password-form').onsubmit=e=>{e.preventDefault();submit(e.currentTarget,async()=>{const password=$('#new-password').value;if(password!==$('#new-confirm').value)throw Error('两次新密码不一致');const r=await client.request('change-password','POST',{currentPassword:$('#old-password').value,password});client.replaceSession(r);if(alive(n)){toast('密码已更新，其他设备已退出。');dashboard();}});};$('#recovery-form').onsubmit=e=>{e.preventDefault();submit(e.currentTarget,async()=>{const r=await client.request('recovery-code','POST',{password:$('#recovery-password').value});if(alive(n))recovery(r.recoveryCode,'新的恢复码已生成，旧码已失效。');});};
  }
  $('#player-account').onclick=()=>client.user?dashboard():auth();updateHeader();client.refresh().catch(()=>{});
  return {schedule:data=>client.schedule(data),pause:()=>client.pause(),open:()=>client.user?dashboard():auth(),client};
}
